package com.example.payment.architecturetest;

import static com.tngtech.archunit.lang.syntax.ArchRuleDefinition.classes;
import static com.tngtech.archunit.library.Architectures.layeredArchitecture;

import com.tngtech.archunit.core.domain.JavaClasses;
import com.tngtech.archunit.core.importer.ClassFileImporter;
import com.tngtech.archunit.core.importer.ImportOption;
import com.tngtech.archunit.lang.ArchRule;
import org.junit.jupiter.api.Test;

/**
 * Enforces the layering the module structure already implies:
 * domain -> application -> infrastructure -> app.
 *
 * These run only during "mvn verify" (failsafe, *ArchTest naming), never during the
 * plain "mvn test" save-loop, so a layer leak is caught by the build without slowing
 * down day-to-day unit testing.
 */
class LayeredArchitectureArchTest {

    private static final String DOMAIN = "com.example.payment.domain..";
    private static final String APPLICATION = "com.example.payment.application..";
    private static final String INFRASTRUCTURE = "com.example.payment.infrastructure..";
    private static final String APP = "com.example.payment.app..";

    private final JavaClasses classes = new ClassFileImporter()
            .withImportOption(ImportOption.Predefined.DO_NOT_INCLUDE_TESTS)
            .importPackages("com.example.payment");

    @Test
    void layers_are_respected() {
        ArchRule rule = layeredArchitecture()
                .consideringOnlyDependenciesInLayers()
                .layer("Domain").definedBy(DOMAIN)
                .layer("Application").definedBy(APPLICATION)
                .layer("Infrastructure").definedBy(INFRASTRUCTURE)
                .layer("App").definedBy(APP)
                .whereLayer("Domain").mayOnlyBeAccessedByLayers("Application", "Infrastructure", "App")
                .whereLayer("Application").mayOnlyBeAccessedByLayers("Infrastructure", "App")
                .whereLayer("Infrastructure").mayOnlyBeAccessedByLayers("App")
                .whereLayer("App").mayNotBeAccessedByAnyLayer();

        rule.check(classes);
    }

    @Test
    void domain_does_not_depend_on_outer_layers() {
        ArchRule rule = classes().that().resideInAPackage(DOMAIN)
                .should().onlyDependOnClassesThat()
                .resideOutsideOfPackages(APPLICATION, INFRASTRUCTURE, APP);

        rule.check(classes);
    }

    @Test
    void application_does_not_depend_on_infrastructure_or_app() {
        ArchRule rule = classes().that().resideInAPackage(APPLICATION)
                .should().onlyDependOnClassesThat()
                .resideOutsideOfPackages(INFRASTRUCTURE, APP);

        rule.check(classes);
    }
}
